//! Draft Block 7 coverage and a quiescent [`WipeRegistry`] wipe test.
//!
//! These tests are not sufficient to claim the roadmap gates. The large corpus is generated by a
//! test source, not read from an encrypted world-line, and resident-cache accounting does not
//! measure all search allocations. The wipe test does not exercise concurrent access. Replace-all
//! crash atomicity also requires a different commit path and failure-injection coverage (AUDIT D-81).

#![cfg(unix)]

use std::fs;
use std::num::NonZeroU32;
use std::path::PathBuf;
use std::sync::{Arc, Mutex};

use holonomy_line::{LineHeader, LineManifest, LineSlab, LineStyleRun, WorldLine};
use holonomy_seal::{
    confirm_compaction, create_capsule_for, generate_container_id, ArenaSlot, CanarySet,
    KdfParamsRecord, MasterKeys, ParamsClass, SecretArenas,
};
use holonomy_text::{
    copy, Alignment, Appended, DocStyle, DocStyleSpan, Draft, FontFamily, Heading, ListKind,
    OpenSources, ResidentSet, SearchMatch, SegmentId, SegmentSink, SegmentSource, Selection, Slab,
    Spine, StyleMap, StylePatch, ToolbarState, TriState, Typing, WipeRegistry,
};

struct Temp(PathBuf);

impl Drop for Temp {
    fn drop(&mut self) {
        let _ = fs::remove_file(&self.0);
    }
}

fn temp_path(tag: &str) -> Temp {
    let id = generate_container_id().expect("entropy");
    let hex: String = id.iter().map(|b| format!("{b:02x}")).collect();
    Temp(std::env::temp_dir().join(format!("holonomy-ribbon-{tag}-{hex}.wavefunction")))
}

fn to_line_slabs(slabs: &[Slab]) -> Vec<LineSlab> {
    slabs
        .iter()
        .map(|s| LineSlab {
            segment: s.segment().get(),
            start: s.start(),
            len: s.len(),
        })
        .collect()
}

fn to_line_manifest(slabs: Vec<LineSlab>, styles: &StyleMap) -> LineManifest {
    let mut runs = Vec::with_capacity(styles.runs().len());
    for span in styles.runs() {
        let st = span.style;
        let (list_kind, list_depth, list_start) = st.list.to_wire();
        runs.push(LineStyleRun {
            start: span.start,
            end: span.end,
            flags: st.flags_byte(),
            family: st.family.code(),
            heading: st.heading.code(),
            alignment: st.alignment.code(),
            list_kind,
            list_depth,
            blockquote: st.blockquote.min(8),
            size_milli: st.size_milli.max(1),
            list_start,
            link_id: st.link_id.map_or(0, NonZeroU32::get),
        });
    }
    LineManifest {
        slabs,
        styles: runs,
        links: styles.links().to_vec(),
    }
}

fn spine_from_line_manifest(manifest: &LineManifest) -> Spine {
    let slabs: Vec<Slab> = manifest
        .slabs
        .iter()
        .map(|s| Slab::new(SegmentId::new(s.segment), s.start, s.len))
        .collect();
    let runs: Vec<DocStyleSpan> = manifest
        .styles
        .iter()
        .filter_map(|r| {
            let style = DocStyle::from_wire(
                r.flags,
                r.family,
                r.heading,
                r.alignment,
                r.list_kind,
                r.list_depth,
                r.blockquote,
                r.size_milli,
                r.list_start,
                r.link_id,
            )?;
            Some(DocStyleSpan {
                start: r.start,
                end: r.end,
                style,
            })
        })
        .collect();
    let styles = StyleMap::from_raw(runs, manifest.links.clone());
    Spine::from_slabs_and_styles(slabs, styles)
}

struct LineStore(WorldLine);

impl SegmentSink for LineStore {
    fn append_segment(&mut self, plaintext: &[u8]) -> Result<Appended, String> {
        let receipt = self
            .0
            .append_segments(&[plaintext])
            .map_err(|e| e.to_string())?;
        Ok(Appended {
            segment: SegmentId::new(receipt.segment_count.saturating_sub(1)),
            witness_sequence: receipt.witness_sequence,
            segment_root: receipt.segment_root,
            bytes_written: receipt.bytes_appended,
        })
    }

    fn append_segment_with_manifest(
        &mut self,
        plaintext: &[u8],
        before: &[Slab],
        after: &[Slab],
        styles: &StyleMap,
    ) -> Result<Appended, String> {
        let new_seg = self.0.segment_count();
        let new_len = u32::try_from(plaintext.len()).map_err(|_| "segment too large".to_owned())?;
        let mut slabs = Vec::with_capacity(before.len() + 1 + after.len());
        slabs.extend(to_line_slabs(before));
        slabs.push(LineSlab {
            segment: new_seg,
            start: 0,
            len: new_len,
        });
        slabs.extend(to_line_slabs(after));
        let receipt = if styles.is_empty() && self.0.is_implicit_after_append(&[plaintext], &slabs)
        {
            self.0
                .append_segments(&[plaintext])
                .map_err(|e| e.to_string())?
        } else {
            let full = to_line_manifest(slabs, styles);
            self.0
                .append_segments_with_full_manifest(&[plaintext], &full)
                .map_err(|e| e.to_string())?
        };
        Ok(Appended {
            segment: SegmentId::new(new_seg),
            witness_sequence: receipt.witness_sequence,
            segment_root: receipt.segment_root,
            bytes_written: receipt.bytes_appended,
        })
    }

    fn commit_manifest(&mut self, slabs: &[Slab], styles: &StyleMap) -> Result<(), String> {
        let full = to_line_manifest(to_line_slabs(slabs), styles);
        self.0
            .commit_full_manifest(&full)
            .map(|_| ())
            .map_err(|e| e.to_string())
    }
}

impl SegmentSource for LineStore {
    fn load(&mut self, segment: SegmentId) -> Result<Vec<u8>, String> {
        self.0
            .open_segment(segment.get())
            .map(|opened| opened.to_vec())
            .map_err(|e| e.to_string())
    }
}

#[test]
fn gate_1_every_toolbar_action_round_trips_across_save_reopen_and_compaction() {
    let source_path = temp_path("gate1-src");
    let compact_path = temp_path("gate1-compact");
    let salt = [0x41; 64];
    let params = KdfParamsRecord {
        m_kib: 8_192,
        t: 1,
        p: 1,
    };
    let passphrase = b"ribbon-gate-1-passphrase";
    let keys = MasterKeys::derive(passphrase, &salt, None, ParamsClass::Test).unwrap();
    let (capsule, dem) = create_capsule_for(keys.unwrap_key(), None).unwrap();
    let header = LineHeader::new(params, salt, capsule).unwrap();
    let old_file_id = *header.file_id();
    let line = WorldLine::create(&source_path.0, header, dem.duplicate()).unwrap();

    // Small 64-byte buffer capacity forces multiple sealed segments across the prose.
    let mut typing = Typing::new(LineStore(line), 64);
    let prose = concat!(
        "Document Title Banner\n",
        "Chapter One: Quiet Architecture\n",
        "Subtitle in H2 with sans family\n",
        "Section H3 centered subheading\n",
        "Bold, italic, underline, strikethrough, and inline code_span sample.\n",
        "* Structural bullet item at depth one\n",
        "1. Structural numbered item at depth two\n",
        "> Nested blockquote wisdom at depth two\n",
        "---\n",
        "Justified prose paragraph before the footer.\n",
        "See reference alpha and reference beta at the end-aligned footer.\n"
    );
    typing.insert(prose.as_bytes()).unwrap();
    typing.flush().unwrap();
    assert!(
        typing.spine().slab_count() >= 4,
        "prose must span multiple sealed segments"
    );

    let find_range = |needle: &str| -> (u64, u64) {
        let start = prose.find(needle).expect("substring present") as u64;
        (start, start + needle.len() as u64)
    };

    // 1. Title, H1, H2, H3 + font families Serif, Sans, Mono + custom sizes + alignments.
    let (t_s, t_e) = find_range("Document Title Banner\n");
    typing
        .apply_style(
            t_s,
            t_e,
            &StylePatch {
                heading: Some(Heading::Title),
                family: Some(FontFamily::Serif),
                ..StylePatch::default()
            },
        )
        .unwrap();

    let (h1_s, h1_e) = find_range("Chapter One: Quiet Architecture\n");
    typing
        .apply_style(
            h1_s,
            h1_e,
            &StylePatch {
                heading: Some(Heading::H1),
                family: Some(FontFamily::Serif),
                size_milli: Some(1_600),
                ..StylePatch::default()
            },
        )
        .unwrap();

    let (h2_s, h2_e) = find_range("Subtitle in H2 with sans family\n");
    typing
        .apply_style(
            h2_s,
            h2_e,
            &StylePatch {
                heading: Some(Heading::H2),
                family: Some(FontFamily::Sans),
                size_milli: Some(1_300),
                ..StylePatch::default()
            },
        )
        .unwrap();

    let (h3_s, h3_e) = find_range("Section H3 centered subheading\n");
    typing
        .apply_style(
            h3_s,
            h3_e,
            &StylePatch {
                heading: Some(Heading::H3),
                alignment: Some(Alignment::Center),
                size_milli: Some(1_100),
                ..StylePatch::default()
            },
        )
        .unwrap();

    // 2. Character marks: bold, italic, underline, strikethrough, code_span (Mono).
    let (b_s, b_e) = find_range("Bold");
    typing
        .apply_style(
            b_s,
            b_e,
            &StylePatch {
                bold: Some(true),
                ..StylePatch::default()
            },
        )
        .unwrap();
    let (i_s, i_e) = find_range("italic");
    typing
        .apply_style(
            i_s,
            i_e,
            &StylePatch {
                italic: Some(true),
                ..StylePatch::default()
            },
        )
        .unwrap();
    let (u_s, u_e) = find_range("underline");
    typing
        .apply_style(
            u_s,
            u_e,
            &StylePatch {
                underline: Some(true),
                ..StylePatch::default()
            },
        )
        .unwrap();
    let (st_s, st_e) = find_range("strikethrough");
    typing
        .apply_style(
            st_s,
            st_e,
            &StylePatch {
                strikethrough: Some(true),
                ..StylePatch::default()
            },
        )
        .unwrap();
    let (c_s, c_e) = find_range("code_span");
    typing
        .apply_style(
            c_s,
            c_e,
            &StylePatch {
                code_span: Some(true),
                family: Some(FontFamily::Mono),
                size_milli: Some(900),
                ..StylePatch::default()
            },
        )
        .unwrap();

    // 3. Real structural lists, blockquote, horizontal rule, Justify/End alignment, and two links.
    let (ul_s, ul_e) = find_range("* Structural bullet item at depth one\n");
    typing
        .apply_style(
            ul_s,
            ul_e,
            &StylePatch {
                list: Some(ListKind::Bullet { depth: 1 }),
                ..StylePatch::default()
            },
        )
        .unwrap();

    let (ol_s, ol_e) = find_range("1. Structural numbered item at depth two\n");
    typing
        .apply_style(
            ol_s,
            ol_e,
            &StylePatch {
                list: Some(ListKind::Ordered { depth: 2, start: 1 }),
                ..StylePatch::default()
            },
        )
        .unwrap();

    let (bq_s, bq_e) = find_range("> Nested blockquote wisdom at depth two\n");
    typing
        .apply_style(
            bq_s,
            bq_e,
            &StylePatch {
                blockquote: Some(2),
                ..StylePatch::default()
            },
        )
        .unwrap();

    let (hr_s, hr_e) = find_range("---\n");
    typing
        .apply_style(
            hr_s,
            hr_e,
            &StylePatch {
                horizontal_rule: Some(true),
                ..StylePatch::default()
            },
        )
        .unwrap();

    let (jf_s, jf_e) = find_range("Justified prose paragraph before the footer.\n");
    typing
        .apply_style(
            jf_s,
            jf_e,
            &StylePatch {
                alignment: Some(Alignment::Justify),
                ..StylePatch::default()
            },
        )
        .unwrap();

    let (ft_s, ft_e) =
        find_range("See reference alpha and reference beta at the end-aligned footer.\n");
    typing
        .apply_style(
            ft_s,
            ft_e,
            &StylePatch {
                alignment: Some(Alignment::End),
                ..StylePatch::default()
            },
        )
        .unwrap();

    let (l1_s, l1_e) = find_range("reference alpha");
    typing
        .set_link(l1_s, l1_e, Some("https://holonomy.local/alpha"))
        .unwrap();
    let (l2_s, l2_e) = find_range("reference beta");
    typing
        .set_link(l2_s, l2_e, Some("https://holonomy.local/beta"))
        .unwrap();

    // Law U0 check: selection spanning Bold + plain + italic reports Mixed (`—`) for bold/italic
    // and Uniform Sans for family, while spanning Serif + Sans reports Mixed for family & size.
    let mixed_marks: ToolbarState = typing.toolbar_state(b_s, i_e);
    assert_eq!(mixed_marks.bold, TriState::Mixed);
    assert_eq!(mixed_marks.italic, TriState::Mixed);
    assert_eq!(mixed_marks.family, TriState::Uniform(FontFamily::Sans));
    assert_eq!(mixed_marks.bold.display_or_dash(|v| v.to_string()), "\u{2014}");

    let mixed_family: ToolbarState = typing.toolbar_state(h1_s, h2_e);
    assert_eq!(mixed_family.family, TriState::Mixed);
    assert_eq!(mixed_family.size_milli, TriState::Mixed);
    assert_eq!(mixed_family.heading, TriState::Mixed);

    // Flush & persist full v2 styled manifest to disk.
    typing.flush().unwrap();
    let expected_styles = typing.spine().styles().clone();
    let full_doc_toolbar = typing.toolbar_state(0, prose.len() as u64);
    drop(typing);

    // Reopen from disk, authenticate every record via `verify()`, and reconstruct Spine + StyleMap.
    let reopened = WorldLine::open(&source_path.0, dem.duplicate()).unwrap();
    let report = reopened.verify().unwrap();
    assert_eq!(report.plaintext_bytes_verified, prose.len() as u64);

    let manifest = reopened.document_manifest();
    let reopened_spine = spine_from_line_manifest(&manifest);
    assert_eq!(reopened_spine.styles(), &expected_styles);
    assert_eq!(
        reopened_spine.toolbar_state(0, prose.len() as u64),
        full_doc_toolbar
    );
    assert_eq!(reopened_spine.toolbar_state(b_s, i_e), mixed_marks);
    assert_eq!(reopened_spine.toolbar_state(h1_s, h2_e), mixed_family);

    let mut res = ResidentSet::new(LineStore(reopened), 4 * 1024 * 1024, 64).unwrap();
    let roundtrip_bytes = copy(
        &reopened_spine,
        &Draft::new(),
        &OpenSources::new(),
        &[],
        &mut res,
        Selection::between(0, prose.len() as u64),
    )
    .unwrap();
    assert_eq!(roundtrip_bytes.as_slice(), prose.as_bytes());

    // Also verify active compaction preserves byte-identical style state & plaintext.
    let reopened_for_compact = WorldLine::open(&source_path.0, dem).unwrap();
    let approval = confirm_compaction(
        passphrase,
        &salt,
        None,
        &params,
        keys.unwrap_key(),
        &old_file_id,
    )
    .unwrap();
    let (new_capsule, new_dem) = create_capsule_for(keys.unwrap_key(), None).unwrap();
    let new_header = LineHeader::new(params, salt, new_capsule).unwrap();
    let compacted = reopened_for_compact
        .compact_active_to(&compact_path.0, new_header, &new_dem, approval)
        .unwrap();
    compacted.verify().unwrap();

    let compacted_spine = spine_from_line_manifest(&compacted.document_manifest());
    assert_eq!(compacted_spine.styles(), &expected_styles);
    let mut compact_res = ResidentSet::new(LineStore(compacted), 4 * 1024 * 1024, 64).unwrap();
    let compacted_bytes = copy(
        &compacted_spine,
        &Draft::new(),
        &OpenSources::new(),
        &[],
        &mut compact_res,
        Selection::between(0, prose.len() as u64),
    )
    .unwrap();
    assert_eq!(compacted_bytes.as_slice(), prose.as_bytes());
}

struct StreamingCorpus {
    segment_count: u64,
    extra_segments: Arc<Mutex<Vec<Vec<u8>>>>,
    loads: u64,
}

impl StreamingCorpus {
    const SEG_LEN: usize = 65_536;

    fn generate_segment(&self, segment_id: SegmentId) -> Result<Vec<u8>, String> {
        let segment = segment_id.get();
        if segment < self.segment_count {
            let mut buf = vec![b' '; Self::SEG_LEN];
            // Fill with 6-byte words `"word0 "` (about 10,922 per 64 KiB segment;
            // 2,748 segments total 180,092,928 bytes).
            let pat = b"word0 ";
            for (i, slot) in buf.iter_mut().enumerate() {
                *slot = pat[i % pat.len()];
            }
            // Place mid-slab needles in segments 100 and 1800.
            if segment == 100 || segment == 1800 {
                buf[1024..1032].copy_from_slice(b"holonomy");
            }
            // Place slab-boundary-straddling needles across 500|501, 1500|1501, and 2500|2501:
            // `"holo"` in the last 4 bytes of segment N and `"nomy"` in the first 4 bytes of N+1.
            if segment == 500 || segment == 1500 || segment == 2500 {
                buf[Self::SEG_LEN - 4..Self::SEG_LEN].copy_from_slice(b"holo");
            }
            if segment == 501 || segment == 1501 || segment == 2501 {
                buf[0..4].copy_from_slice(b"nomy");
            }
            Ok(buf)
        } else {
            let idx = usize::try_from(segment - self.segment_count)
                .map_err(|_| "segment index overflow".to_owned())?;
            let guard = self.extra_segments.lock().unwrap();
            guard
                .get(idx)
                .cloned()
                .ok_or_else(|| format!("unknown replacement segment {segment_id}"))
        }
    }
}

impl SegmentSource for StreamingCorpus {
    fn load(&mut self, segment: SegmentId) -> Result<Vec<u8>, String> {
        self.loads += 1;
        self.generate_segment(segment)
    }
}

struct CorpusSink {
    next_id: u64,
    appended: Arc<Mutex<Vec<Vec<u8>>>>,
}

impl SegmentSink for CorpusSink {
    fn append_segment(&mut self, plaintext: &[u8]) -> Result<Appended, String> {
        let seg = self.next_id;
        self.next_id += 1;
        self.appended.lock().unwrap().push(plaintext.to_vec());
        Ok(Appended {
            segment: SegmentId::new(seg),
            witness_sequence: seg,
            segment_root: [0xAB; 32],
            bytes_written: plaintext.len() as u64,
        })
    }
}

#[test]
fn gate_2_streaming_find_and_replace_all_over_30m_words_preserve_l2_residency_bound() {
    // 2,748 distinct 64 KiB segments = 180,092,928 bytes, over 30 M six-byte words.
    const SEGMENTS: u64 = 2_748;
    const SEG_LEN: u32 = 65_536;
    const BUDGET_L2: usize = 4 * 1024 * 1024;

    let slabs: Vec<Slab> = (0..SEGMENTS)
        .map(|seg| Slab::new(SegmentId::new(seg), 0, SEG_LEN))
        .collect();
    let spine = Spine::from_slabs(slabs);
    let initial_len = spine.len();
    assert_eq!(initial_len, SEGMENTS * u64::from(SEG_LEN));
    assert!(
        initial_len / 6 >= 30_000_000,
        "corpus must contain at least 30,000,000 words"
    );

    let shared_extra = Arc::new(Mutex::new(Vec::new()));
    let source = StreamingCorpus {
        segment_count: SEGMENTS,
        extra_segments: Arc::clone(&shared_extra),
        loads: 0,
    };
    let mut residency = ResidentSet::new(source, BUDGET_L2, 1024).unwrap();

    // Fault in 3 viewport segments (simulating an open editor screen) and record exact L-2 bytes.
    for seg in [0u64, 1, 2] {
        let _ = residency.fault_in(SegmentId::new(seg)).unwrap();
    }
    let resident_before = residency.resident_bytes();
    assert!(resident_before > 0 && resident_before <= BUDGET_L2);
    // Count the scan itself, not the three viewport faults above.
    residency.source_mut().loads = 0;

    let sink = CorpusSink {
        next_id: SEGMENTS,
        appended: shared_extra,
    };
    let mut typing = Typing::resume(sink, spine.clone(), 4096);

    // 1. Streaming Find across all 30M+ words: ResidentSet byte count must not move by 1 byte.
    let matches = typing
        .find_all(b"holonomy", residency.source_mut())
        .unwrap();
    assert_eq!(
        residency.resident_bytes(),
        resident_before,
        "streaming find_all must not fault segments into ResidentSet"
    );
    assert_eq!(
        residency.source_mut().loads,
        SEGMENTS,
        "every 64 KiB segment of the 30M-word corpus must be streamed"
    );
    let expected = vec![
        SearchMatch {
            start: 100 * 65_536 + 1024,
            end: 100 * 65_536 + 1032,
        },
        SearchMatch {
            start: 500 * 65_536 + 65_532,
            end: 501 * 65_536 + 4,
        },
        SearchMatch {
            start: 1500 * 65_536 + 65_532,
            end: 1501 * 65_536 + 4,
        },
        SearchMatch {
            start: 1800 * 65_536 + 1024,
            end: 1800 * 65_536 + 1032,
        },
        SearchMatch {
            start: 2500 * 65_536 + 65_532,
            end: 2501 * 65_536 + 4,
        },
    ];
    assert_eq!(matches, expected);

    // 2. Transactional Replace-All (`"holonomy"` -> `"HOLONOMY_V6"`, +3 bytes per match = +15).
    let replaced = typing
        .replace_all(b"holonomy", b"HOLONOMY_V6", residency.source_mut())
        .unwrap();
    assert_eq!(replaced, 5);
    assert_eq!(
        residency.resident_bytes(),
        resident_before,
        "replace_all must preserve exact L-2 residency without faulting corpus into ResidentSet"
    );
    assert_eq!(typing.document_len(), initial_len + 15);
    assert!(typing
        .find_all(b"holonomy", residency.source_mut())
        .unwrap()
        .is_empty());
    assert_eq!(
        typing
            .find_all(b"HOLONOMY_V6", residency.source_mut())
            .unwrap()
            .len(),
        5
    );

    // 3. Single atomic undo step restores the exact 30M-word Spine pointer in O(1).
    assert!(typing.undo().unwrap());
    assert!(typing.spine().ptr_eq(&spine));
    assert_eq!(typing.document_len(), initial_len);
    assert_eq!(residency.resident_bytes(), resident_before);
}

#[test]
fn gate_3_formatting_torture_corpus_across_every_slab_boundary_reverts_in_one_undo() {
    // 8 slabs of 64 bytes each = 512 bytes; 7 slab boundaries at 64, 128, 192, 256, 320, 384, 448.
    let mut initial_segments = Vec::new();
    let mut slabs = Vec::new();
    for i in 0..8u64 {
        let mut chunk = format!("slab-{i}-alpha-target-omega-").into_bytes();
        chunk.resize(64, b'.');
        initial_segments.push(chunk);
        slabs.push(Slab::new(SegmentId::new(i), 0, 64));
    }
    let shared_extra = Arc::new(Mutex::new(initial_segments));
    let mut source = StreamingCorpus {
        segment_count: 0,
        extra_segments: Arc::clone(&shared_extra),
        loads: 0,
    };
    let sink = CorpusSink {
        next_id: 8,
        appended: shared_extra,
    };
    let mut typing = Typing::resume(sink, Spine::from_slabs(slabs), 128);

    // Seed distinct rich-text styles straddling EVERY slab boundary (k * 64 - 12 .. k * 64 + 12).
    for boundary in 1..8u64 {
        let center = boundary * 64;
        let patch = StylePatch {
            bold: Some(boundary % 2 == 1),
            italic: Some(boundary % 3 == 0),
            underline: Some(boundary % 2 == 0),
            code_span: Some(boundary == 4),
            heading: Some(match boundary {
                1 => Heading::H1,
                2 => Heading::H2,
                3 => Heading::H3,
                _ => Heading::None,
            }),
            alignment: Some(match boundary % 3 {
                0 => Alignment::End,
                1 => Alignment::Center,
                _ => Alignment::Start,
            }),
            list: Some(if boundary == 5 {
                ListKind::Bullet { depth: 2 }
            } else if boundary == 6 {
                ListKind::Ordered { depth: 1, start: 1 }
            } else {
                ListKind::None
            }),
            blockquote: Some((boundary as u8) % 3),
            ..StylePatch::default()
        };
        typing.apply_style(center - 12, center + 12, &patch).unwrap();
    }
    let seeded_spine = typing.spine().clone();
    assert!(
        seeded_spine.styles().runs().len() >= 7,
        "torture corpus must carry distinct styles across all 7 slab boundaries"
    );

    // Apply one sweeping formatting override across the entire multi-slab torture corpus.
    let sweep = StylePatch {
        bold: Some(true),
        strikethrough: Some(true),
        family: Some(FontFamily::Mono),
        size_milli: Some(1_200),
        ..StylePatch::default()
    };
    typing.apply_style(0, typing.document_len(), &sweep).unwrap();
    assert!(!typing.spine().ptr_eq(&seeded_spine));
    assert_eq!(
        typing.toolbar_state(0, typing.document_len()).bold,
        TriState::Uniform(true)
    );

    // ONE single `undo()` reverts every boundary-straddling style across all 8 slabs!
    assert!(typing.undo().unwrap());
    assert!(typing.spine().ptr_eq(&seeded_spine));
    assert_eq!(typing.spine().styles(), seeded_spine.styles());

    // Now execute a transactional `replace_all` across all 8 styled slabs and verify ONE `undo()`
    // reverts both text and every slab-straddling style span identically.
    let count = typing
        .replace_all(b"target", b"REPLACED_TOKEN", &mut source)
        .unwrap();
    assert_eq!(count, 8);
    assert!(typing.undo().unwrap());
    assert!(typing.spine().ptr_eq(&seeded_spine));
    assert_eq!(typing.spine().styles(), seeded_spine.styles());
}

struct SealWipeBridge(Arc<SecretArenas>);

impl WipeRegistry for SealWipeBridge {
    unsafe fn register(&self, ptr: *mut u8, len: usize) -> Option<usize> {
        // SAFETY: `ResidentSet` and `Typing` hold `[ptr, ptr + len)` live and unmoved until
        // calling `unregister` in their RAII destructors / reallocation paths.
        unsafe { self.0.register(ptr, len) }.map(|slot| slot.index())
    }

    fn unregister(&self, slot: usize) {
        if let Some(handle) = ArenaSlot::from_index(slot) {
            self.0.unregister(handle);
        }
    }
}

#[test]
fn wipe_registry_arms_and_zeroizes_resident_set_and_typing_buffers_in_place() {
    let arenas = SecretArenas::new();
    let mut canaries = CanarySet::new(4, 256);
    assert_eq!(canaries.arm_all(&arenas), 4);
    let bridge: Arc<dyn WipeRegistry> = Arc::new(SealWipeBridge(Arc::clone(&arenas)));

    let shared_extra = Arc::new(Mutex::new(Vec::new()));
    let mut source = StreamingCorpus {
        segment_count: 2,
        extra_segments: Arc::clone(&shared_extra),
        loads: 0,
    };
    let _ = source.load(SegmentId::new(0)).unwrap();
    let mut residency = ResidentSet::new(source, 4 * 1024 * 1024, 256).unwrap();
    residency.set_wipe_registry(Arc::clone(&bridge));
    let _ = residency.fault_in(SegmentId::new(0)).unwrap();

    let sink = CorpusSink {
        next_id: 2,
        appended: shared_extra,
    };
    let mut typing = Typing::resume(
        sink,
        Spine::from_slabs(vec![Slab::new(SegmentId::new(0), 0, 65_536)]),
        256,
    );
    typing.set_wipe_registry(Arc::clone(&bridge));
    typing.insert(b"top-secret live typing buffer").unwrap();

    // 4 canaries + 1 resident slab + 1 open typing buffer = at least 6 armed arenas.
    assert!(arenas.armed_count() >= 6);
    assert_eq!(canaries.sample_ghosts().ghost_canaries, 4);

    // Fire emergency volatile wipe directly through `SecretArenas` (as the background reaper does).
    let stats = arenas.wipe();
    assert!(stats.arenas_wiped >= 6);
    assert!(stats.bytes_wiped > 65_536);

    let ghosts = canaries.sample_ghosts();
    assert_eq!(ghosts.canaries_sampled, 4);
    assert_eq!(ghosts.ghost_canaries, 0);
    assert_eq!(ghosts.ghost_bytes, 0);

    // Both the resident slab and the open typing buffer must now read back as all-zero bytes.
    let slab_after = residency.fault_in(SegmentId::new(0)).unwrap();
    assert!(slab_after.iter().all(|&b| b == 0));
    assert!(typing.pending().iter().all(|&b| b == 0));

    // Dropping both structures must cleanly unregister every remaining slot down to the 4 canaries.
    drop(typing);
    drop(residency);
    assert_eq!(arenas.armed_count(), 4);
    drop(canaries);
    assert_eq!(arenas.armed_count(), 0);
}
